#!/usr/bin/env node
/* MVP Trainer V5 R7.2 - Player Visual Refinement installer */
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const target = path.join(root, "src", "features", "music", "MusicMiniPlayer.tsx");
const expectedSha256 = "b930a33b22a1ea8e71fce34988c6b1168fc3c72676776dcd309a9820e8c9946d";
const replacementBase64 = "";

function fail(message) {
  console.error(`\nR7.2 STOPPED: ${message}\n`);
  process.exit(1);
}

if (!fs.existsSync(target)) {
  fail(`Could not find ${path.relative(root, target)}. Run this from the MVP Trainer repo root.`);
}

const current = fs.readFileSync(target, "utf8");
if (!current.includes("export function MusicMiniPlayer")) {
  fail("The target file does not look like the current MVP MusicMiniPlayer. Nothing was changed.");
}

const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backup = `${target}.bak-r7-2-${stamp}`;
fs.copyFileSync(target, backup);

const replacement = Buffer.from(replacementBase64, "base64");
fs.writeFileSync(target, replacement);

console.log("\nMVP Trainer V5 R7.2 Player Visual Refinement applied successfully.");
console.log(`Updated: ${path.relative(root, target)}`);
console.log(`Backup:  ${path.relative(root, backup)}`);
console.log(`SHA-256: ${expectedSha256}`);
console.log("\nNext: run npm run build, then test desktop + mobile before committing.\n");
